#version 450
layout(local_size_x = 64) in;
layout(std430, binding = 0) buffer B { float o[]; };
layout(binding = 1) uniform U { float a; float b; float c; } u;
void main() {
    uint i = gl_GlobalInvocationID.x;
    o[i] = o[i] * (sqrt(u.a) * u.b + u.c);
}

#version 450
layout(location = 0) in vec3 wpos;
layout(location = 1) flat in uint mat;
layout(location = 2) flat in vec4 tint;
layout(location = 0) out vec4 col;
layout(push_constant) uniform PC { float gain; } pc;
void main() {
    float m = float(mat) * 0.25 + pc.gain;
    vec3 t = tint.rgb * tint.a * m;
    col = vec4(t * wpos.y, 1.0);
}

#version 450
layout(location = 0) out vec4 col;
layout(push_constant) uniform PC { vec2 invres; vec2 centre; float k; } pc;
void main() {
    vec2 uv = gl_FragCoord.xy * pc.invres;
    vec2 d = uv - pc.centre;
    float v = 1.0 - dot(d, d) * pc.k;
    col = vec4(v, v, v, 1.0);
}

#version 450
layout(location = 0) in uint packed;
layout(location = 1) in vec2 pos;
layout(location = 0) out vec3 col;
layout(location = 1) flat out uint row;
layout(location = 2) out float lum;
void main() {
    uint r = packed & 255u;
    uint g = (packed >> 8) & 255u;
    int sb = int(packed << 8) >> 24;
    uint hi = packed >> 16;
    col = vec3(float(r), float(g) / 255.0, float(sb));
    lum = float(hi);
    row = uint(gl_InstanceIndex) / 3u;
    gl_Position = vec4(pos, 0.0, 1.0);
}
